/// <summary>
/// AVAReplenishRawMaterial form
/// </summary>
[Form]
public class AVAReplenishRawMaterial extends FormRun
{
    ProdTable   prodTableLoc;
    ProdBOM     prodBOMLoc;
    FormDataSource fdsLoc;
    container   queryRangeLoc;

}

/// <summary>
/// init method for AVAReplenishRawMaterial form
/// </summary>
void init()
{
    super();

    if (element.args().record())
    {
        switch (element.args().record().TableId)
        {
            case tablenum(ProdTable):
                prodTableLoc      = element.args().record();
        }

        switch (element.args().callerName())
        {
            case 'ProdTableOverview':
                FormRun formRunLoc = element.args().caller();
                fdsLoc          = formRunLoc.datasource('ProdBOM');
                prodBOMLoc = fdsLoc.getFirst();

                while(prodBOMLoc)
                {
                    if(!conFind(queryRangeLoc, prodBOMLoc.ItemId))
                    {
                        queryRangeLoc += queryValue(prodBOMLoc.ItemId);
                    }

                    prodBOMLoc = fdsLoc.getNext();
                }
                break;
        }
    }
    else
    {
        Error::wrongUseOfFunction(funcName());
    }  
}

public void replenishRawMaterial()
{
    AVAReplenishRawMaterial replenishRawMaterial = AVAReplenishRawMaterial::construct();

    replenishRawMaterial.parmProdTable(prodTableLoc);
    replenishRawMaterial.parmItemId(ItemId.valueStr());
    replenishRawMaterial.parmOprNum(OprNum.value());
    replenishRawMaterial.parmQty(Quantity.realValue());

    replenishRawMaterial.startOperation();
}

/// <summary>
/// Replaced normal with InventTable lookup
/// </summary>
public void lookup()
{
    InventItemIdLookupSimple inventItemIdLookupSimple = InventItemIdLookupSimple::construct();

    Query query = new Query();
    QueryBuildDataSource qbds;
    QueryBuildRange qbr;
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(InventItemIdLookupSimpleView), this);

    sysTableLookup.addLookupField(fieldNum(InventItemIdLookupSimpleView, ItemId), true);
    sysTableLookup.addLookupField(fieldNum(InventItemIdLookupSimpleView, NDXModelNumber));
    sysTableLookup.addLookupField(fieldNum(InventItemIdLookupSimpleView, NameAlias));
    sysTableLookup.addLookupField(fieldNum(InventItemIdLookupSimpleView, ProductName));
    sysTableLookup.addLookupField(fieldNum(InventItemIdLookupSimpleView, ItemGroupId));
    sysTableLookup.addLookupField(fieldNum(InventItemIdLookupSimpleView, KCS_KAOItemState));
    sysTableLookup.addLookupField(fieldNum(InventItemIdLookupSimpleView, AVANetWeight));

    qbds = query.addDataSource(tableNum(InventItemIdLookupSimpleView));
    qbds.addOrderByField(fieldNum(InventItemIdLookupSimpleView, ItemId));

    qbr = qbds.addRange(fieldNum(InventItemIdLookupSimpleView, ItemId));
    qbr.value(con2Str(queryRangeLoc));

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();

    //super();
}

/// <summary>
/// modified method
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean ret;

    ret = super();

    UnitId.text(InventTable::find(this.valueStr()).bomUnitId());

    return ret;
}

/// <summary>
/// Lookup filtered prodRoute
/// </summary>
public void lookup()
{
    Query query = new Query();
    QueryBuildDataSource qbds;
    QueryBuildRange qbr;
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(ProdRoute), this);

    sysTableLookup.addLookupField(fieldNum(ProdRoute, ProdId));
    sysTableLookup.addLookupField(fieldNum(ProdRoute, OprNum), true);
    sysTableLookup.addLookupField(fieldNum(ProdRoute, OprPriority));
    sysTableLookup.addLookupField(fieldNum(ProdRoute, OprNumNext));

    qbds = query.addDataSource(tableNum(ProdRoute));
    qbds.addOrderByField(fieldNum(ProdRoute, OprNum));

    qbr = qbds.addRange(fieldNum(ProdRoute, ProdId));
    qbr.value(queryValue(prodTableLoc.ProdId));

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();

    //super();
}

/// <summary>
/// clicked method of Button OkButton
/// </summary>
